  it('bodyInsertionPoint finds the body-level section properties, not a tracked-change copy', () => {
    // When Word tracks a change to section properties it nests a
    // <w:sectPrChange> inside <w:sectPr>, and that element holds a second,
    // complete <w:sectPr> with the previous settings. A plain
    // lastIndexOf('<w:sectPr') lands on the nested one and paragraphs get
    // spliced in as children of the section properties. Anchoring the pattern
    // does not help — the nested element is a real <w:sectPr>. Measured: both
    // searches return offset 128 here where the correct answer is 45.
    const tracked =
      '<w:body>' +
      '<w:p><w:r><w:t>Body</w:t></w:r></w:p>' +
      '<w:sectPr>' +
      '<w:pgSz w:w="12240" w:h="15840"/>' +
      '<w:sectPrChange w:id="1" w:author="Ana"><w:sectPr><w:pgSz w:w="15840" w:h="12240"/></w:sectPr></w:sectPrChange>' +
      '</w:sectPr>' +
      '</w:body>';

    expect(bodyInsertionPoint(tracked)).toBe(tracked.indexOf('<w:sectPr>'));

    const spliced = insertParagraphsXml(tracked, buildParagraphXml('Appended'));
    expect(spliced.indexOf('Appended')).toBeLessThan(spliced.indexOf('<w:sectPr>'));

    // Still correct on ordinary documents, and on a multi-section one where
    // earlier <w:sectPr> elements are nested inside <w:pPr>.
    const multi =
      '<w:body><w:p><w:pPr><w:sectPr><w:pgSz w:w="1" w:h="2"/></w:sectPr></w:pPr></w:p>' +
      '<w:p/><w:sectPr><w:pgSz w:w="3" w:h="4"/></w:sectPr></w:body>';
    expect(bodyInsertionPoint(multi)).toBe(multi.lastIndexOf('<w:sectPr>'));

    // A section with no page-setup overrides is a self-closing <w:sectPr/>.
    // It is a complete element with no closing tag, so a depth counter that
    // treats it as an opener never comes back down and stops recognising the
    // real body-level element. Measured: that returns offset 20, inside
    // <w:pPr>, where the correct answer is 82.
    const selfClosing =
      '<w:body><w:p><w:pPr><w:sectPr/></w:pPr></w:p>' +
      '<w:p><w:r><w:t>Body</w:t></w:r></w:p>' +
      '<w:sectPr><w:pgSz w:w="12240" w:h="15840"/></w:sectPr></w:body>';
    expect(bodyInsertionPoint(selfClosing)).toBe(selfClosing.lastIndexOf('<w:sectPr>'));

    // And a document whose only section properties are self-closing.
    const onlySelfClosing = '<w:body><w:p/><w:sectPr/></w:body>';
    expect(bodyInsertionPoint(onlySelfClosing)).toBe(onlySelfClosing.indexOf('<w:sectPr/>'));

    // Minor 1: a document whose only <w:sectPr> is <w:pPr>-nested — e.g. the
    // body-level one was removed — has no <w:sectPr> at pPr-depth zero at all.
    // Tracking only <w:sectPr> nesting (not <w:pPr> depth) reported this one
    // as body-level regardless, landing an insert inside <w:pPr>. The correct
    // answer is the fallback: the end of the body.
    const onlyPPrNested =
      '<w:body><w:p><w:pPr><w:sectPr><w:pgSz w:w="1" w:h="2"/></w:sectPr></w:pPr></w:p></w:body>';
    expect(bodyInsertionPoint(onlyPPrNested)).toBe(onlyPPrNested.lastIndexOf('</w:body>'));
  });

