  it('setCoreProperty replaces a self-closing property instead of duplicating it', () => {
    // Word writes an unset property as a self-closing element. Measured against
    // the earlier implementation: the first call appended a duplicate, and the
    // second — which `idempotentHint: true` promises is safe — spanned from the
    // leftover `<dc:title/>` to the duplicate's closing tag and deleted
    // `<dc:creator>Bob</dc:creator>` outright, producing malformed XML that was
    // then uploaded with success: true.
    const start =
      '<cp:coreProperties xmlns:cp="c" xmlns:dc="d"><dc:title/><dc:creator>Bob</dc:creator></cp:coreProperties>';

    const once = setCoreProperty(start, 'dc:title', 'New Title');
    expect(once).toContain('<dc:title>New Title</dc:title>');
    expect(once).not.toContain('<dc:title/>');
    expect(once).toContain('<dc:creator>Bob</dc:creator>');

    // Genuinely idempotent: a second identical call changes nothing.
    expect(setCoreProperty(once, 'dc:title', 'New Title')).toBe(once);
    expect(once.match(/<dc:title[^>]*>/g) || []).toHaveLength(1);
  });

  it('setCoreProperty refuses a core.xml it cannot append to', () => {
    // Silently returning the input and reporting success is the failure mode
    // this guard exists to prevent.
    expect(() => setCoreProperty('<somethingElse/>', 'dc:title', 'X')).toThrow(/coreProperties/);
  });

  it('get-comments keeps multi-paragraph comments readable', async () => {
    // A comment body can hold several paragraphs. Measured: concatenating every
    // <w:t> across the whole body produced "First point.Second point.".
    const zip = await openDocx(sampleDocx());
    writePart(
      zip,
      'word/comments.xml',
      '<?xml version="1.0"?><w:comments xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">' +
        '<w:comment w:id="1" w:author="Ana" w:date="2026-08-01T10:00:00Z">' +
        '<w:p><w:r><w:t>First point.</w:t></w:r></w:p>' +
        '<w:p><w:r><w:t>Second </w:t></w:r><w:r><w:t>point.</w:t></w:r></w:p>' +
        '</w:comment></w:comments>',
    );
    vi.stubGlobal(
      'fetch',
      vi.fn(async () => binaryResponse(await packDocx(zip))),
    );

    const sessionId = await initAndOpen();
    sendToolCall(sessionId, 'get-comments', { itemId: 'i1' });
    const result = await waitForType('tool_result');

    const comments = (result.result as any).comments as Array<Record<string, unknown>>;
    expect(comments).toHaveLength(1);
    // Paragraphs separated, and the split runs inside the second one rejoined.
    expect(comments[0].text).toBe('First point.\nSecond point.');
  });

