  it('convert-to-pdf asks Graph for a PDF and stores the result', async () => {
    const pdf = Buffer.from('%PDF-1.7\n%%EOF\n');
    const fetchMock = vi.fn(async (_url: string, init: RequestInit) =>
      init?.method === 'PUT'
        ? jsonResponse({ id: 'pdf-1', name: 'Quarterly.pdf' })
        : binaryResponse(pdf),
    );
    vi.stubGlobal('fetch', fetchMock);

    const sessionId = await initAndOpen();
    sendToolCall(sessionId, 'convert-to-pdf', { path: 'Reports/Quarterly.docx' });
    const result = await waitForType('tool_result');

    expect((result.result as any).success).toBe(true);

    const download = graphCall(fetchMock, (u) => u.includes('format=pdf'));
    expect(download?.[0]).toContain('/me/drive/root:/Reports/Quarterly.docx:/content?format=pdf');

    const upload = graphCall(fetchMock, (u) => u.includes('Quarterly.pdf'));
    expect(upload?.[0]).toContain('@microsoft.graph.conflictBehavior=fail');
    expect(uploadedBytes(fetchMock)!.equals(pdf)).toBe(true);
  });

