  it('declares all four annotations on every tool', async () => {
    const sessionId = await initAndOpen();

    host.send({ ...createEnvelope('list_tools'), sessionId } as MessageBase);
    const toolsList = await waitForType('tools_list');
    const tools = toolsList.tools as Array<{ name: string; annotations?: Record<string, unknown> }>;

    // Without this an empty list would satisfy the loop and the test would pass
    // while asserting nothing — the exact failure it exists to catch.
    expect(tools).toHaveLength(13);

    for (const tool of tools) {
      expect(tool.annotations, `${tool.name} has no annotations`).toBeDefined();
      for (const hint of ['readOnlyHint', 'destructiveHint', 'idempotentHint', 'openWorldHint']) {
        expect(typeof tool.annotations?.[hint], `${tool.name} does not declare ${hint}`).toBe(
          'boolean',
        );
      }
    }
  });

  it('marks every mutating tool as destructive', async () => {
    // Spec §7.5: a deliberate departure from the suite-wide rule that
    // destructiveHint means irreversible. Here every mutation is a
    // read-modify-write the app cannot undo, so the two sets coincide exactly.
    const sessionId = await initAndOpen();

    host.send({ ...createEnvelope('list_tools'), sessionId } as MessageBase);
    const toolsList = await waitForType('tools_list');
    const tools = toolsList.tools as Array<{ name: string; annotations?: Record<string, unknown> }>;

    const mutating = tools
      .filter((t) => t.annotations?.readOnlyHint === false)
      .map((t) => t.name)
      .sort();
    const destructive = tools
      .filter((t) => t.annotations?.destructiveHint === true)
      .map((t) => t.name)
      .sort();

    expect(mutating).toEqual([
      'append-paragraphs',
      'convert-to-pdf',
      'create-document',
      'delete-paragraph',
      'insert-image',
      'insert-page-break',
      'insert-table',
      'replace-text',
      'update-document-properties',
    ]);
    expect(destructive).toEqual(mutating);
  });
